import pandas as pd
import numpy as np

def calculate_compliance_weight():
    # 定义合规维度权重模型
    dimensions = {
        '版权审查': {'weight': 0.35, 'factors': ['音频监测', '图像比对', '人工复核']},
        '内容审核': {'weight': 0.40, 'factors': ['实时弹幕监控', '商品信息验证', '主播资质审查']},
        '投诉处理': {'weight': 0.25, 'factors': ['响应时效', '处置效率', '追溯机制']}
    }

    # 构建评分矩阵
    scores = {
        '平台A': {'版权审查': 85, '内容审核': 90, '投诉处理': 78},
        '平台B': {'版权审查': 76, '内容审核': 82, '投诉处理': 88}
    }

    # 计算综合合规度
    results = {}
    for platform, data in scores.items():
        weighted_score = sum(data[dim] * weight for dim, weight in {
            '版权审查': 0.35, '内容审核': 0.40, '投诉处理': 0.25
        }.items())
        results[platform] = {
            '综合合规度': round(weighted_score, 1),
            '改进优先级': max(data, key=lambda k: 100 - data[k])
        }

    return results

calculate_compliance_weight()
